группа('дуэль → секреты: слой правок снимка');
{
  const SE = await модуль('snapshot-edits.js');
  const SG = await модуль('render/secrets-grid.js');
  const HS = await модуль('hud-snapshot.js');
  const { settings: Sx } = await модуль('settings.js');
  const м = {};
  const былСТ = globalThis.SillyTavern;
  globalThis.SillyTavern = { getContext: () => ({ chat: [], chatMetadata: м }) };
  const факт = 'Мари знала о помолвке Дамиана с Валерией заранее';
  равно('ключ секрета не зависит от хвоста фразы', SE.ключСекрета(факт), SE.ключСекрета('Мари знала о помолвке Дамиана с Валерией'));
  const секреты = [
    { fact: факт, level: 'critical', status: 'unknown', knows: [{ name: 'Мари', source: 'сама' }], hidden: ['Лена', 'Дамиан'] },
    { fact: 'У Дарена долг казино в Монако', level: 'high', knows: [{ name: 'Дарен' }], hidden: [] },
    { fact: 'Лена тайно встречается с Ноланом', level: 'medium', knows: [{ name: 'Лена' }], hidden: [] },
  ];
  const ход = { characters: [
    { 'Имя': 'Дамиан', 'Словесная дуэль': 'ini: Дамиан, 60; gv: Мари призналась, что знала о помолвке с Валерией; tn: ссора', 'Глубина конфликта': 'wy: помолвка с Валерией; dys: 2' },
    { 'Имя': 'Лена' },
  ] };
  const предл = SE.всплывшиеСекреты(секреты, [{ уступка: 'Мари призналась, что знала о помолвке с Валерией', суть: '' }], ['Мари', 'Дамиан', 'Лена'], SG.клеткаСекрета);
  проверить('всплыло: уступка в дуэли — «знает» для Дамиана и Лены, Мари уже знает', предл.length === 2 && предл.every(п => п.значение === 'known') && !предл.some(п => п.кто === 'Мари'), JSON.stringify(предл.map(п => [п.кто, п.значение])));
  проверить('всплыло: только суть спора — «подозревает»', SE.всплывшиеСекреты(секреты, [{ уступка: '', суть: 'помолвка Дамиана с Валерией' }], ['Лена'], SG.клеткаСекрета)[0]?.значение === 'suspected');
  проверить('всплыло: одно общее слово — не совпадение', !SE.совпадаетССекретом('помолвка', факт));
  const былаСетка = Sx.secretsGrid; Sx.secretsGrid = 'on';
  const сетка = SG.сеткаСекретов(секреты, ход);
  проверить('сетка: предложение «отметить знает» с кнопками, клетка подсвечена', /hud-sgrid-raise/.test(сетка) && /data-value="known"/.test(сетка) && /data-value="dismissed"/.test(сетка) && /is-proposed/.test(сетка));
  SE.правитьСнимок(SE.путьСекрета(факт, 'Лена'), 'known', 299);
  const сетка2 = SG.сеткаСекретов(секреты, ход);
  проверить('после «отметить»: у Лены правка и расхождение (модель пишет «не знает»), снова не спрашивает про Лену', /has-edit/.test(сетка2) && /is-conflict/.test(сетка2) && !/при Лена/.test(сетка2) && /data-sec-edit="sec\|[^"]*\|Лена" data-value=""/.test(сетка2));
  SE.правитьСнимок(SE.путьСекрета(факт, 'Дамиан'), 'dismissed');
  const сетка3 = SG.сеткаСекретов(секреты, ход);
  проверить('«нет» — больше не спрашивает про Дамиана', !/при Дамиан/.test(сетка3), (сетка3.match(/<em>при [^<]*/g) || []).join(' | '));
  const снимок = { me: { sec: [{ f: факт, lv: 'critical', knw: [{ n: 'Мари', src: 'сама' }], hd: ['Лена', 'Дамиан'] }] } };
  const строка = HS.строкаСнимка(снимок, false);
  проверить('снимок модели: Лена — в knw с пометкой игрока и не в hd; Дамиан («нет») не тронут; исходный объект цел', /"n":"Лена","src":"узнал\(а\) — отметил игрок"/.test(строка) && /"hd":\["Дамиан"\]/.test(строка) && снимок.me.sec[0].hd.length === 2, строка.slice(0, 400));
  проверить('снять правку', SE.снятьПравку(SE.путьСекрета(факт, 'Лена')) && !SE.правкаСекрета(факт, 'Лена'));
  Sx.secretsGrid = былаСетка;
  globalThis.SillyTavern = былСТ;
}

