группа('custom-stats: свои статы');
{
  const К = await модуль('custom-stats.js');
  const s = { customStats: [{ id: 'a', name: 'Голод', hint: 'насколько голоден', view: 'pct', who: 'chars' }, { id: 'b', name: 'Мана', view: 'scale', who: 'user' }, { id: 'c', name: 'Розыск', view: 'stars', who: 'story', tab: 'world' }, { id: 'd', name: '', who: 'chars' }, { id: 'e', name: 'голод', who: 'chars' }] };
  const статы = К.своиСтаты(s);
  проверить('без имени и дубли имени у одного владельца отброшены', статы.map(с => с.id).join() === 'a,b,c');
  const п = К.промптСвоихСтатов(s);
  проверить('промт: имена, где писать, пояснение, формат', п.includes('"Голод" — in EVERY character object in "cs", inside its "Cst" object') && п.includes('What it tracks: насколько голоден') && п.includes('"Розыск" — in the top-level "cst" object') && п.includes('0-100'));
  проверить('без игрока статы игрока не просим', !К.промптСвоихСтатов(s, { игрок: false }).includes('Мана'));
  {
    // Шаблон us/cs называет поле "Cst": правило «в us только перечисленные поля»
    // иначе отсекало статы игрока.
    const Ст = await модуль('settings.js'); const Пр = await модуль('prompt.js');
    const было = [Ст.settings.customStats, Ст.settings.enableUserBlock];
    Ст.settings.customStats = s.customStats; Ст.settings.enableUserBlock = true;
    const весь = Пр.buildDynamicPrompt({ nsfw: false, cacheStable: true });
    const us = весь.slice(весь.indexOf('"us": {'), весь.indexOf('\n }', весь.indexOf('"us": {')));
    проверить('в шаблоне us и cs есть поле Cst, когда есть статы игрока и персонажей', us.includes('"Cst"') && весь.slice(весь.indexOf('"cs": ['), весь.indexOf('"us": {')).includes('"Cst"'));
    const шаблонCs = весь.slice(весь.indexOf('"cs": ['), весь.indexOf('"us": {'));
    проверить('в шаблоне — имена статов своего владельца: Мана у игрока, Голод у персонажей', us.includes('"Cst": {"Мана": "[a number 0-10') && !us.includes('Голод') && шаблонCs.includes('"Cst": {"Голод": "[a number 0-100') && !шаблонCs.includes('Мана'));
    Ст.settings.customStats = []; проверить('без своих статов поля Cst в шаблоне нет', !Пр.buildDynamicPrompt({ nsfw: false, cacheStable: true }).includes('"Cst": {'));
    [Ст.settings.customStats, Ст.settings.enableUserBlock] = было;
  }
  проверить('свой промт: {{stats}} заменяется, без него — список в конце', К.промптСвоихСтатов({ ...s, customStatsPrompt: 'МОИ: {{stats}} КОНЕЦ' }).includes('МОИ: - "Голод"') && /^\n\nМОИ$\n- "Голод"/m.test('\n\n' + К.промптСвоихСтатов({ ...s, customStatsPrompt: 'МОИ' }).trim()));
  проверить('нет статов — промт пуст', К.промптСвоихСтатов({}) === '');
  равно('число и пояснение', [К.числоИПояснение('70 — сыт'), К.числоИПояснение('7/10: устал'), К.числоИПояснение('4★'), К.числоИПояснение('нет числа')].map(x => [x.число, x.пояснение]), [[70, 'сыт'], [7, 'устал'], [4, ''], [null, 'нет числа']]);
  проверить('значение по имени без учёта регистра, заглушка — пусто', К.значениеСтата({ 'ГОЛОД': '40' }, 'голод') === '40' && К.значениеСтата({ Голод: 'empty' }, 'Голод') === '');
  const блок = К.блокСтата(статы[0], '140 — не ел сутки');
  проверить('блок: имя пользователя, проценты обрезаны до 100', блок.includes('>Голод<') && блок.includes('width:100%') && блок.includes('data-cst="a"') && блок.includes('не ел сутки'));
  проверить('пустое значение — без блока', К.блокСтата(статы[0], '') === '');
  const звёзды = К.блокСтата({ id: 'x', name: 'Р', view: 'stars' }, '3');
  проверить('звёзды: пять, горят три; метки', (звёзды.match(/<i class="is-on">/g) || []).length === 3 && (звёзды.match(/hud-cst-stars[\s\S]*?<\/span>/)[0].match(/<i[ >]/g) || []).length === 5 && (К.блокСтата({ id: 'y', name: 'М', view: 'tags' }, 'а; б').match(/hud-v-tag/g) || []).length === 2);
  проверить('уровень по доле шкалы: низко, средне, высоко', К.блокСтата({ id: 'a', name: 'Г', view: 'pct' }, '10').includes(' lv-1') && К.блокСтата({ id: 'a', name: 'Г', view: 'scale' }, '5').includes(' lv-2') && К.блокСтата({ id: 'a', name: 'Г', view: 'stars' }, '5').includes(' lv-3'));
  проверить('цвет: без выбора — акцент темы, без kind и style', !/kind-|style="--kind/.test(К.блокСтата({ id: 'c', name: 'Ц', view: 'num' }, '5')));
  проверить('цвет группы — класс kind-*', К.блокСтата({ id: 'c', name: 'Ц', view: 'num', color: 'mind' }, '5').includes(' kind-mind '));
  проверить('свой цвет — --kind в style, мусор отброшен', К.блокСтата({ id: 'c', name: 'Ц', view: 'num', color: '#12ab34' }, '5').includes('style="--kind:#12ab34"') && !/style=|kind-/.test(К.блокСтата({ id: 'c', name: 'Ц', view: 'num', color: 'red;x:1' }, '5')) && !/kind-custom/.test(К.блокСтата({ id: 'c', name: 'Ц', view: 'num', color: 'custom' }, '5')));
  проверить('значок: свой или по виду, неизвестный — по виду', К.блокСтата({ id: 'a', name: 'Г', view: 'pct', icon: 'heart' }, '1').includes('hud-cst-medal') && К.блокСтата({ id: 'a', name: 'Г', view: 'pct', icon: 'heart' }, '1') !== К.блокСтата({ id: 'a', name: 'Г', view: 'pct', icon: 'нет' }, '1') && К.блокСтата({ id: 'a', name: 'Г', view: 'pct', icon: 'нет' }, '1') === К.блокСтата({ id: 'a', name: 'Г', view: 'pct' }, '1'));
  проверить('общий выключатель: ни статов, ни строчки в промте', К.своиСтаты({ ...s, customStatsOn: false }).length === 0 && К.промптСвоихСтатов({ ...s, customStatsOn: false }) === '');
  проверить('строка поля получает data-k, один раз', К.пометитьСтроку('<div class="hud-row x">a</div><div class="hud-row">b</div>', 'тело') === '<div class="hud-row x" data-k="тело">a</div><div class="hud-row">b</div>');
  const р = К.раскладкаСтатов([{ after: 'тело', html: 'A' }, { after: '^', html: 'B' }, { after: 'нет-поля', html: 'C' }, { after: '', html: 'D' }]);
  проверить('раскладка: начало, после поля, остаток в конце', р.после('^') === 'B' && р.после('тело') === 'A' && р.после('тело') === '' && р.остаток() === 'CD');
  const вк = К.вставитьВВкладку('<div class="hud-tab-content active" id="x"><div>мир</div></div>', [{ after: '^', html: '[в]' }, { after: '', html: '[к]' }]);
  проверить('вкладка без полей: начало и конец', вк === '<div class="hud-tab-content active" id="x">[в]<div>мир</div>[к]</div>', вк);
  const д = Sch.normalizeJSONData(P.parseHUDComplex(hud({ sc: { T: '10:00' }, cs: [{ N: 'Лилиан', Cst: { Голод: '70 — сыта', Место: 'x' } }], us: { A: '20', Cst: { Мана: 5 } }, cst: { Розыск: '3' } })));
  проверить('разбор: Cst персонажа и игрока, cst истории — без перевода имён', д.characters[0].Cst && д.characters[0].Cst['Голод'] === '70 — сыта' && д.characters[0].Cst['Место'] === 'x' && д.custom['Розыск'] === '3', JSON.stringify([д.characters[0].Cst, д.user && д.user.Cst, д.custom]));
}

группа('group-cards: карточки участников группы');
{
  const Г = await модуль('group-cards.js');
  const персонаж = (имя, описание, характер = '') => ({ name: имя, avatar: имя + '.png', data: { description: описание, personality: характер } });
  const ctx = (режим, говорит) => ({
    groupId: 'g1', characterId: говорит,
    characters: [персонаж('Анна', 'Рыжая, 25 лет.'), персонаж('Борис', 'Высокий, седой.', 'Ворчун'), персонаж('Вера', 'Слепая гадалка.'), персонаж('Глеб', 'Не в группе.')],
    groups: [{ id: 'g1', members: ['Анна.png', 'Борис.png', 'Вера.png'], disabled_members: [], generation_mode: режим }],
  });
  const ответ = Г.карточкиГруппы(ctx(0, 1));
  проверить('ответ по очереди: карточки всех, кроме говорящего', ответ.includes('### Анна') && ответ.includes('### Вера') && !ответ.includes('### Борис') && !ответ.includes('Глеб'), ответ);
  проверить('перегенерация: карточки всех участников, характер тоже', /### Борис\nВысокий, седой\.\nPersonality: Ворчун/.test(Г.карточкиГруппы(ctx(0, 1), { всех: true })));
  проверить('склеенные карточки Таверна кладёт сама — в ответе пусто', Г.карточкиГруппы(ctx(1, 1)) === '' && Г.карточкиГруппы(ctx(1, 1), { всех: true }).includes('### Анна'));
  const выкл = ctx(0, 0); выкл.groups[0].disabled_members = ['Вера.png'];
  проверить('выключенный участник не попадает', !Г.карточкиГруппы(выкл).includes('Вера'));
  проверить('не группа — пусто', Г.карточкиГруппы({ characterId: 0, characters: [персонаж('Анна', 'x')] }) === '' && Г.карточкиГруппы(null) === '');
  const длинное = Г.карточкиГруппы({ ...ctx(0, 1), characters: [персонаж('Анна', 'Очень длинное описание. '.repeat(300))].concat(ctx(0, 1).characters.slice(1)) });
  проверить('длинное описание обрезано', длинное.length < 3000 && длинное.includes(' …'), String(длинное.length));
}

группа('правка поля в карточке и поля игрока');
{
  const Р = await модуль('field-edit.js');
  проверить('код поля по data-k: у персонажа и игрока одни коды', Р.кодПоля('char', 'роль') === 'R' && Р.кодПоля('user', 'роль') === 'R' && Р.кодПоля('user', 'мысли') === 'Th' && Р.кодПоля('user', 'nope') === '');
  const сырой = { cs: [{ N: 'Лилиан', R: 'травница', G: { nw: 'спать', sn: 'есть' }, Cst: { Голод: '70' } }], us: { A: '20' }, cst: { Розыск: '3' } };
  проверить('значение для окошка: объект — «метка: значение; …»', Р.текущееЗначение(сырой, { кто: 'Лилиан', код: 'G' }) === 'nw: спать; sn: есть');
  проверить('правка поля персонажа, стата, стата истории и нового поля игрока',
    Р.применитьПравку(сырой, { кто: 'Лилиан', код: 'R', значение: 'ведьма' }) && сырой.cs[0].R === 'ведьма'
    && Р.применитьПравку(сырой, { кто: 'Лилиан', стат: 'голод', значение: '20 — поела' }) && сырой.cs[0].Cst['Голод'] === '20 — поела'
    && Р.применитьПравку(сырой, { кто: 'story', стат: 'Розыск', значение: '5' }) && сырой.cst['Розыск'] === '5'
    && Р.применитьПравку(сырой, { кто: 'user', код: 'Th', значение: '' }) && сырой.us.Th === 'empty');
  проверить('чужое имя — некуда писать', !Р.применитьПравку(сырой, { кто: 'Марк', код: 'R', значение: 'x' }));
  const Ст = await модуль('settings.js'); const Пр = await модуль('prompt.js');
  {
    // Язык из таблицы: значения HUD — на нём, ключи и коды — английские.
    const англ = ['- 🌍 LANG: write values in English; character names follow "N".', 'The place is in English words.', '🌍 Write all HUD values in English, even if earlier HUDs used another language.'].join('\n');
    const кит = Пр.наЯзыкеТаблицы(англ, 'Chinese (中文)');
    проверить('язык из таблицы: строка LANG на языке перевода', кит.includes('write values in Chinese (中文) (keys and short codes stay exactly as specified, in English)'));
    проверить('язык из таблицы: последняя строка тоже', кит.includes('Write all HUD values in Chinese (中文)') && !кит.includes('in English, even if'));
    проверить('язык из таблицы: место — словами этого языка', кит.includes('The place is in Chinese (中文) words'));
    проверить('без языка из таблицы инструкция не меняется', Пр.наЯзыкеТаблицы(англ, null) === англ);
  }
  const было = [Ст.settings.enableUserBlock, Ст.settings.userAllFields]; Ст.settings.enableUserBlock = true; Ст.settings.userAllFields = true;
  const весь = Пр.buildDynamicPrompt({ nsfw: false, cacheStable: true });
  Ст.settings.userAllFields = false;
  const безПолей = Пр.buildDynamicPrompt({ nsfw: false, cacheStable: true });
  проверить('без галочки «все поля» — у игрока только его основа', !безПолей.slice(безПолей.indexOf('"us": {')).split(String.fromCharCode(10) + ' }')[0].includes('"Th":'));
  const us = весь.slice(весь.indexOf('"us": {'), весь.indexOf(String.fromCharCode(10) + ' }', весь.indexOf('"us": {')));
  проверить('игроку в шаблоне — поля персонажей (роль, мысли, инвентарь, доверие), без W', ['"R":', '"Th":', '"I":', '"Tr":', '"G":'].every(к => us.includes(к)) && !us.includes('"W":') && !us.includes('"N":'));
  [Ст.settings.enableUserBlock, Ст.settings.userAllFields] = было;
  const Ch = await модуль('render/character.js');
  const д = Sch.normalizeJSONData(P.parseHUDComplex(hud({ sc: { T: '10:00' }, cs: [{ N: 'Лилиан' }], us: { A: '20', R: 'студентка-архивист', Th: 'только бы не опоздать', I: 'ключ; фонарь' } })));
  const карточка = Ch.buildUserHTML(д.user, 'uu', true, д.characters);
  проверить('карточка игрока рисует поля персонажей', /Роль/.test(карточка) && /студентка-архивист/.test(карточка) && /только бы не опоздать/.test(карточка) && /фонарь/.test(карточка) && карточка.includes('data-who="user"'));
}

группа('hud-block: удалить HUD из чата');
{
  const блок = hud({ sc: { T: '10:00' }, cs: [{ N: 'Лилиан' }] });
  проверить('ответ без HUD, хвост убран', B.текстБезHUD('Ответ.\n\n' + блок) === 'Ответ.');
  проверить('блок в середине: один перенос, как стоял', B.текстБезHUD('До\n' + блок + '\nПосле') === 'До\nПосле');
  проверить('пустая строка вокруг сохраняется', B.текстБезHUD('До\n\n' + блок + '\n\nПосле') === 'До\n\nПосле');
  проверить('только HUD — «…»', B.текстБезHUD(блок) === '…');
  const сводка = '[HUD_SUMMARY] 01.01 · 10:00 [/HUD_SUMMARY]';
  проверить('[HUD_SUMMARY] остаётся', B.текстБезHUD('Ответ.\n' + сводка + '\n' + блок) === 'Ответ.\n' + сводка);
  const план = '<plan>в конце [HUD] json</plan>\nОтвет.\n' + блок;
  проверить('упоминание в <plan> не съедает ответ', B.текстБезHUD(план) === '<plan>в конце [HUD] json</plan>\nОтвет.');
  проверить('текст без HUD не меняется ни на символ', B.текстБезHUD('  Отступ\n\n\n\nабзац  ') === '  Отступ\n\n\n\nабзац  ');
  const m = { mes: 'Б\n' + блок, swipe_id: 1, swipes: ['А\n' + блок, 'Б\n' + блок], extra: { hud_versions: [{ hud: блок }], api: 'x' }, swipe_info: [{ extra: { hud_music: {} } }, { extra: {} }] };
  const n = B.вычиститьHUDИзСообщения(m);
  проверить('сообщение: текст, все свайпы и extra HUD', n === 4 && m.mes === 'Б' && m.swipes.join('|') === 'А|Б' && !('hud_versions' in m.extra) && m.extra.api === 'x' && !('hud_music' in m.swipe_info[0].extra), JSON.stringify(m).slice(0, 300));
  проверить('повторная очистка ничего не находит', B.вычиститьHUDИзСообщения(m) === 0);
  const сКопией = { mes: 'А\n' + блок, extra: { display_text: 'А\n' + блок + '\n<comics>' } };
  B.вычиститьHUDИзСообщения(сКопией);
  проверить('копия для показа (display_text) — тоже без HUD', сКопией.extra.display_text === 'А\n<comics>');
}

