    МА.пометитьПамятьСнимка(сн3, короткий);
    проверить('журнал: давность без старых сообщений, новый ход дописан', сн3.me.fct[0].startsWith('[f1 · 8 days ago]') && сн3.me.fct[1].startsWith('[f2 · today]') && 'дарен уехал' in мета.tavernosHudFirstSeen.fct, сн3.me.fct);
