  const тп = [{ target: 'Марк', chatName: 'Марк → Олег', messages: ['Марк -> Олег: Пробей его | 19:10 | Read', 'Олег -> Марк: [CALL: outgoing, missed] | 19:12', 'Марк -> Олег: Только ей ни слова | 19:25 | Deleted', 'Марк -> Олег: [DRAFT] Она с ним | 21:38'] }];
  const р = Ip.перепискаДляВида(тп[0]);
  проверить('переписка: собеседник — не владелец, звонок по-русски', р.чат === 'Олег' && р.строки[1].текст === '⟨звонок: исходящий, пропущен⟩', р);
  проверить('переписка: удалённое и черновик помечены, текст без меток', р.строки[2].удалено && р.строки[3].черновик && р.строки[3].текст === 'Она с ним');
