  St.settings.interceptsView = 'reel';
  проверить('катушки: стёртый участок ленты', Ip.buildInterceptsHTML(тп, 'i', true, '17.10.2024').includes('class="erased"'));
  St.settings.interceptsView = 'classic';
  проверить('«Телефон» — прежний макет', Ip.buildInterceptsHTML(тп, 'i', true, '17.10.2024').includes('intercept-mode'));
  const дн = [{ author: 'Мари Беннет', time: '17.10 21:40', text: 'Сегодня **решилась**.', aboutUser: 'Он смотрит иначе', mood: 'anxiety' }];
  St.settings.diaryView = 'book';
  const кн = Dn.buildDiaryHTML(дн, 'd', true);
