группа('прокрутка насквозь');
{
  const Ch = await модуль('scroll-chain.js');
  const окно = { top: 400, bottom: 700 };
  проверить('список весь в окне', Ch.весьНаВиду({ top: 410, bottom: 690 }, [окно]));
  проверить('список выглядывает снизу', !Ch.весьНаВиду({ top: 600, bottom: 880 }, [окно]));
  проверить('список за верхним краем', !Ch.весьНаВиду({ top: 300, bottom: 600 }, [окно]));
  проверить('второе окно тоже считается', !Ch.весьНаВиду({ top: 410, bottom: 690 }, [окно, { top: 0, bottom: 600 }]));
  проверить('список больше окна не запирается', Ch.весьНаВиду({ top: 300, bottom: 900 }, [окно]));
}
{
  const Sc = await модуль('scroll-chain.js');
  const обл = (top, max) => ({ scrollTop: top, scrollHeight: max + 100, clientHeight: 100 });
  const список = обл(50, 50), тело = обл(0, 500), чат = обл(100, 900);
  проверить('пока списку есть куда ехать, его двигает браузер', Sc.шагЦепочки([обл(10, 50), тело], 0, -20) === null && тело.scrollTop === 0);
  проверить('список в конце: сдвиг получает тело', Sc.шагЦепочки([список, тело, чат], 0, -20) === тело && тело.scrollTop === 20 && чат.scrollTop === 100);
  const конецТела = обл(500, 500);
  проверить('тело в конце: сдвиг получает чат', Sc.шагЦепочки([список, конецТела, чат], 0, -20) === чат && чат.scrollTop === 120);
  const верх = обл(0, 50), телоВверху = обл(0, 500), чатВверх = обл(300, 900);
  проверить('вверх то же самое', Sc.шагЦепочки([верх, телоВверху, чатВверх], 0, 30) === чатВверх && чатВверх.scrollTop === 270);
  проверить('ехать некуда — ничего', Sc.шагЦепочки([обл(50, 50), обл(500, 500)], 0, -20) === null);
  const э = (свойства, родитель) => ({ nodeType: 1, parentElement: родитель || null, scrollHeight: 500, clientHeight: 100, id: '', ...свойства });
  const стиль = (e) => e.с;
  const чатЭ = э({ id: 'chat', с: { overflowY: 'auto', touchAction: 'auto' } }), над = э({ с: { overflowY: 'auto', touchAction: 'auto' } }, null);
  чатЭ.parentElement = над;
  const телоЭ = э({ с: { overflowY: 'auto', touchAction: 'pan-y' } }, чатЭ), без = э({ scrollHeight: 100, с: { overflowY: 'auto', touchAction: 'auto' } }, телоЭ);
  const ц = Sc.цепьОт(без, стиль);
  проверить('цепь: только прокручиваемые, чат последний', ц.length === 2 && ц[0] === телоЭ && ц[1] === чатЭ);
  const отдельный = э({ с: { overflowY: 'auto', touchAction: 'auto', overscrollBehaviorY: 'contain' } }, чатЭ);
  проверить('область с contain цепь останавливает', Sc.цепьОт(отдельный, стиль).length === 1);
  проверить('перетаскивание не трогаем', Sc.цепьОт(э({ с: { overflowY: 'visible', touchAction: 'none' } }, телоЭ), стиль).length === 0);
}

