группа('long-list: длинные списки памяти');
{
  const LL = await модуль('render/long-list.js');
  const пункты = Array.from({ length: 80 }, (_, i) => `<p>${i}</p>`);
  const html = LL.длинныйСписок(пункты, 'x');
  const видимые = html.replace(/<template[\s\S]*?<\/template>/g, '');
  проверить('видны последние 25', (видимые.match(/<p>/g) || []).length === LL.ВИДНО_СРАЗУ && видимые.includes('<p>79</p>') && !видимые.includes('<p>54</p>'));
  проверить('ранние — порциями в template, порядок сохранён', (html.match(/<template/g) || []).length === 2 && html.indexOf('<p>0</p>') < html.indexOf('<p>54</p>') && html.indexOf('<p>54</p>') < html.indexOf('<p>55</p>'));
  проверить('на кнопке число скрытых', /data-more-left="55"/.test(html));
  проверить('короткий список — без кнопки', !LL.длинныйСписок(пункты.slice(0, 30), 'x').includes('hud-more-btn'));
}

