группа('carryover: кэш разборов (LRU + время жизни)');
{
  const { КэшРазборов } = await модуль('render/carryover.js');
  const к = new КэшРазборов(3, 1000);
  к.положить('a', 1, 0); к.положить('b', null, 0); к.положить('c', 3, 0);
  проверить('null — это попадание, а не промах', к.взять('b', 10) === null);
  к.взять('a', 10);
  к.положить('d', 4, 10);
  проверить('вытесняется самый давно не нужный', к.взять('c', 20) === undefined && к.взять('a', 20) === 1 && к.size === 3);
  проверить('запись старше времени жизни — промах', к.взять('d', 5000) === undefined);
  проверить('чтение продлевает жизнь', (к.взять('a', 900), к.взять('a', 1800)) === 1);
}

