// Перегенерация одного телефона: из ответа — только cm и phn, в HUD — только они.
{
  const Т = await модуль('phone-regen.js');
  const старый = '[HUD]\n```json\n{\n  "sc": {"T": "21:40 | вечер"},\n  "cs": [{"N": "Вера", "Th": "скобка { в тексте"}],\n  "cm": {"Глеб": {"ow": "Вера", "ms": ["Глеб -> Вера: старое | 20:00 | Read"]}},\n  "phn": {"ow": "Вера", "sq": ["старый запрос"]},\n  "me": {"fct": ["факт"]}\n}\n```\n[/HUD]';
  const новыйТел = { cm: { 'Глеб': { ow: 'Вера', ms: ['Глеб -> Вера: новое {{char}} | 21:30 | Unread'] } }, phn: { ow: 'Вера', sq: ['новый запрос'] } };
  const весьОтвет = 'Она подняла глаза.\n\n[HUD]\n```json\n' + JSON.stringify({ sc: { T: '22:00' }, cs: [{ N: 'Чужой' }], ...новыйТел }) + '\n```\n[/HUD]';
  const из = Т.вырезатьТелефон(весьОтвет);
  проверить('телефон: из целого HUD с прозой — только cm и phn', из && Object.keys(из).sort().join() === 'cm,phn' && из.phn.sq[0] === 'новый запрос');
  проверить('телефон: голый JSON без меток', Т.вырезатьТелефон(JSON.stringify(новыйТел)).cm['Глеб'].ms.length === 1);
  const битый = 'вот: {"sc": {"T": "22:00", "phn": {"ow": "Вера", "sq": ["запрос"]}, "cm": {"Глеб": {"ow": "Вера", "ms": []}} ,,, оборвалось';
  проверить('телефон: разделы из испорченного JSON', (() => { const р = Т.вырезатьТелефон(битый); return р && р.phn && р.phn.sq[0] === 'запрос' && р.cm; })());
  проверить('телефон: без телефона — null', Т.вырезатьТелефон('[HUD]{"sc": {"T": "1"}}[/HUD]') === null);
  const вставлено = Т.вставитьТелефон(старый, из);
  const о = JSON.parse(вставлено.replace(/^\[HUD\]\s*```json\s*/, '').replace(/\s*```\s*\[\/HUD\]$/, ''));
  проверить('телефон: заменены только cm и phn', о.phn.sq[0] === 'новый запрос' && о.cm['Глеб'].ms[0].includes('{{char}}') && о.me.fct[0] === 'факт' && о.cs[0].Th === 'скобка { в тексте' && о.sc.T === '21:40 | вечер');
  проверить('телефон: прочие строки блока — как были', вставлено.includes('"cs": [{"N": "Вера", "Th": "скобка { в тексте"}],') && вставлено.includes('"me": {"fct": ["факт"]}'));
  const разобрать = (б) => JSON.parse(б.replace(/^\[HUD\]\s*```json\s*/, '').replace(/\s*```\s*\[\/HUD\]$/, ''));
  const вложенный = Т.вставитьТелефон('[HUD]\n```json\n{"tp": [{"cm": {"x": 1}}], "cm": {"Старый": {}}}\n```\n[/HUD]', { cm: { 'Новый': {} } });
  проверить('телефон: «cm» внутри другого раздела не трогаем', (() => { const о = разобрать(вложенный); return о.tp[0].cm.x === 1 && о.cm['Новый'] && !о.cm['Старый']; })());
  const массив = Т.вставитьТелефон('[HUD]\n```json\n{"sc": {"T": "1"}, "cm": []}\n```\n[/HUD]', { cm: { 'Новый': {} } });
  проверить('телефон: «cm» массивом заменяется, без второго ключа', (массив.match(/"cm"/g) || []).length === 1 && разобрать(массив).cm['Новый']);
  const безТел = Т.вставитьТелефон('[HUD]\n```json\n{"sc": {"T": "1"}}\n```\n[/HUD]', { phn: { ow: 'Вера' } });
  проверить('телефон: раздела не было — дописан', JSON.parse(безТел.replace(/^\[HUD\]\s*```json\s*/, '').replace(/\s*```\s*\[\/HUD\]$/, '')).phn.ow === 'Вера');
  const П = await модуль('prompt.js');
  const полный = '<hud_instructions>\n## 🎯 TASK\nOutput ONLY one [HUD] block for the latest message.\nThe block holds ONLY valid JSON.\n\n## 📐 RULES\n- 🔤 CODES: коды.\n- 👤 WHO GOES WHERE: персонажи.\n- ⚠️ FORMATTING: формат.\n\n## 🧾 SCHEMA\n\n[HUD]\n```json\n{\n "sc": {\n  "T": "[time]"\n },\n "cm": {\n  "[contact]": {\n   "ow": "[owner: ALWAYS {{char}}]"\n  }\n },\n "phn": {\n  "ow": "[owner {x}]"\n }\n}\n```\n[/HUD]\n\n{{if hudLast}}## 📸 LAST HUD\n{{hudLast}}{{/if}}\n\n🌍 Write all HUD values in Russian.\n</hud_instructions>';
  const тел = П.промптТелефона(полный);
  проверить('телефон: в инструкции только cm и phn', тел.includes('"cm": {') && тел.includes('"phn": {') && !тел.includes('"sc": {') && тел.includes('{{if hudLast}}') && тел.includes('🌍 Write all HUD values'));
  проверить('телефон: из правил — коды и формат, без «кто где»', тел.includes('🔤 CODES') && тел.includes('⚠️ FORMATTING') && !тел.includes('WHO GOES WHERE'));
  проверить('телефон: без телефона в схеме — пусто', П.промптТелефона(полный.replace(/ "cm"[\s\S]*?\n "phn": \{\n  "ow": "\[owner \{x\}\]"\n \}/, ' "x": 1')) === '');
}

