// Время слухов: дата и час хода появления, минуты и секунды не позже его времени.
{
  const В = await модуль('render/rumor-times.js');
  const в = В.времяИзХода('слух', { дата: 'Четверг, 17.10.2024', время: '21:15 | вечер' });
  const сек = (вр) => { const [ч, м, с] = вр.split(':').map(Number); return ч * 3600 + м * 60 + с; };
  проверить('слухи: дата хода, время в пределах часа хода', в && в.дата === '17.10' && в.время.startsWith('21:'));
  проверить('слухи: не позже времени хода', сек(в.время) <= сек('21:15:00') && сек(в.время) >= сек('21:00:00'));
  проверить('слухи: то же время при каждой отрисовке', В.времяИзХода('слух', { дата: 'Четверг, 17.10.2024', время: '21:15' }).время === в.время);
  const ровно = ['a', 'b', 'c', 'd'].map(к => В.времяИзХода(к, { дата: '1.1', время: '21:00' }).время);
  проверить('слухи: в 21:00 — до четверти часа назад, и записи разные', ровно.every(вр => сек(вр) <= сек('21:00:00') && сек(вр) >= сек('20:45:00')) && new Set(ровно).size > 1, ровно);
  проверить('слухи: около полуночи не уходит во вчера', сек(В.времяИзХода('x', { дата: '1.1', время: '00:05' }).время) >= 0);
  проверить('слухи: ход без времени — без метки', В.времяИзХода('x', { дата: '1.1', время: 'вечер' }) === null);
  const впервые = { [В.ключСлуха('Старый слух.')]: { дата: '16.10.2024', время: '09:30', ход: 3 } };
  const времена = В.временаСлухов(['Старый слух', 'Новый слух'], впервые, { дата: '17.10.2024', время: '21:15', ход: 9 }, { запомнить: false });
  проверить('слухи: старый — со временем своего хода, новый — с нынешним', времена.get(В.ключСлуха('Старый слух')).время.startsWith('09:') && времена.get(В.ключСлуха('Старый слух')).ход === 3 && времена.get(В.ключСлуха('Новый слух')).время.startsWith('21:'));
}

// Перевод чата Таверны: блок HUD не переводится и чинится.
{
  const П = await модуль('translate-guard.js');
  const блок = '[HUD]\n\x60\x60\x60json\n{\n "sc": {\n  "T": "21:40 | late evening"\n }\n}\n\x60\x60\x60\n[/HUD]';
  const текст = 'She smiled.\n\nThen she left.\n\n' + блок;
  const тексты = [{ текст, блоки: [[текст.indexOf('[HUD]'), текст.length]] }];
  проверить('перевод: проза без блока — переводится как есть', П.сегментыПеревода('She smiled.', тексты) === null);
  const ч = П.сегментыПеревода('Then she left.\n\n[HUD]\n\x60\x60\x60json', тексты);
  проверить('перевод: кусок с началом блока делится на прозу и блок', ч && ч.length === 2 && !ч[0].hud && ч[0].текст === 'Then she left.\n\n' && ч[1].hud && ч[1].текст.startsWith('[HUD]'));
  const в = П.сегментыПеревода(' "T": "21:40 | late evening"', тексты);
  проверить('перевод: кусок из середины блока не переводится', в && в.length === 1 && в[0].hud);
  const google = 'Она улыбнулась.\n\nПотом ушла.\n\n[ХУД] \n\x60\x60\x60json \n{ \n"ск": { \n«Т»: «21:40 | поздний вечер» \n} \n} \n\x60\x60\x60 \n[/ХУД]';
  const п1 = П.починитьПереведённое(google, [текст]);
  проверить('перевод: переведённый блок Google заменяется оригиналом', п1 === 'Она улыбнулась.\n\nПотом ушла.\n\n' + блок, п1);
  const яндекс = 'Она улыбнулась.\n\n[HUD]\n\x60\x60джон\n{\n "sc": {\n  "Т": "21:40 | поздний вечер".,\n }\n}';
  проверить('перевод: и у Яндекса («\x60\x60джон»)', П.починитьПереведённое(яндекс, [текст]) === 'Она улыбнулась.\n\n' + блок);
  const склеено = 'Она улыбнулась.' + блок.replace('\n "sc"', ' "sc"');
  проверить('перевод: склеенный защитой блок выравнивается по оригиналу', П.починитьПереведённое(склеено, [текст]) === 'Она улыбнулась.' + блок);
  проверить('перевод: целый блок не трогаем', П.починитьПереведённое('Она улыбнулась.\n\n' + блок, [текст]) === null);
  проверить('перевод: без HUD — нечего чинить', П.починитьПереведённое('Привет', ['Hello']) === null);
  проверить('перевод карточки: только строки с латиницей', П.нужноПеревести('light rain, +9°C') && !П.нужноПеревести('21:40') && !П.нужноПеревести('Дождь'));
  проверить('перевод карточки: на английский — кириллицу, на немецкий — всё', П.нужноПеревести('Дождь', 'en') && !П.нужноПеревести('light rain', 'en') && П.нужноПеревести('light rain', 'de') && П.нужноПеревести('Дождь', 'de') && !П.нужноПеревести('5 h', 'de'));
  // Кусок прозы, который встречается и внутри блока: ищем от конца прошлого куска.
  const сДаВБлоке = 'Yes.\n\n[HUD]\n\x60\x60\x60json\n{"Ln": "Yes."}\n\x60\x60\x60\n[/HUD]\n\nYes.';
  const тДа = [{ текст: сДаВБлоке, блоки: [[6, сДаВБлоке.lastIndexOf('[/HUD]') + 6]] }];
  проверить('перевод: проза до блока переводится', П.найтиКусок('Yes.', тДа, 0).части === null);
  проверить('перевод: проза после блока — тоже, по позиции прошлого куска', П.найтиКусок('Yes.', тДа, тДа[0].блоки[0][1]).части === null);
  проверить('перевод: кусок блока — нет', П.найтиКусок('{"Ln": "Yes."}', тДа, 6).части[0].hud === true);
  проверить('перевод: ограждение с кодом в прозе — не блок', П.началоПереведённогоБлока('Пример:\n\x60\x60\x60\nlet x = 1;\nreturn x;\n\x60\x60\x60') === -1);
  проверить('перевод: ограждение с JSON-ключами — блок', П.началоПереведённогоБлока('Текст.\n\n\x60\x60\x60json\n{\n«ск»: {\n«Т»: «21:40»,') === 8);
  проверить('перевод: свой display_text без HUD с кодом в прозе не режем', П.починитьПереведённое('Вот код:\n\x60\x60\x60\nx = 1\ny = 2\n\x60\x60\x60', [текст]) === null);
  // Google приклеивает переведённую метку к прозе: «…ушла.[ХУД]».
  const прилипла = П.починитьПереведённое('Она улыбнулась.[ХУД]\n\x60\x60\x60json\n{\n"ск": {\n«Т»: «21:40»\n}\n}\n\x60\x60\x60\n[/ХУД]', [текст]);
  проверить('перевод: метка, прилипшая к прозе, уходит вместе с блоком', прилипла === 'Она улыбнулась.\n\n' + блок, прилипла);
  const осталась = П.починитьПереведённое('Она улыбнулась.[ХУД]\n\n' + блок, [текст]);
  проверить('перевод: метка над уже починенным блоком убирается', осталась === 'Она улыбнулась.\n\n' + блок, осталась);
  проверить('перевод: скобки перед блоком из оригинала остаются', П.починитьПереведённое('Она засмеялась. [смеётся]\n\n' + блок, ['She laughed. [laughs]\n\n' + блок]) === null);
  {
    let вызовов = 0;
    // Переводчик, который склеивает строки, если их больше двух.
    const склейщик = async (t) => { вызовов++; const l = t.split('\n'); return l.length > 2 ? l.map(x => 'П:' + x).join(' ') : l.map(x => 'П:' + x).join('\n'); };
    const р = await П.перевестиСтроки(склейщик, ['a1', 'b2', 'c3', 'd4', 'e5'], 4000);
    проверить('перевод карточки: склеенная пачка делится пополам, а не на пять запросов', р.size === 5 && р.get('c3') === 'П:c3' && вызовов <= 7, вызовов);
    const р2 = await П.перевестиСтроки(async (t) => t.toUpperCase(), ['x'.repeat(30), 'y'.repeat(30), 'z'.repeat(30)], 50);
    проверить('перевод карточки: пачки по лимиту', р2.size === 3 && р2.get('y'.repeat(30)) === 'Y'.repeat(30));
  }
  {
    const В = П.вернутьПеревод, mes = 'She smiled.', тр = 'Она улыбнулась.';
    проверить('ExtBlocks удалил перевод — возвращаем', JSON.stringify(В(тр, mes, undefined)) === JSON.stringify({ текст: тр, хвост: '' }));
    const р = В(тр, mes, mes + '\n<stats>HP 5</stats>');
    проверить('ExtBlocks записал оригинал со своими блоками — перевод с его блоками', р.текст === тр + '\n<stats>HP 5</stats>' && р.хвост === '\n<stats>HP 5</stats>');
    const р2 = В(р.текст, mes, mes + '\n<stats>HP 4</stats>', р.хвост);
    проверить('ExtBlocks обновил блоки — старые не дублируются', р2.текст === тр + '\n<stats>HP 4</stats>');
    проверить('его собственный текст — не перевод', В(mes + '\n<x/>', mes, undefined) === null);
    проверить('кто-то другой положил свой текст — не трогаем', В(тр, mes, 'Совсем другое') === null);
  }
}

// --- Формат даты и температура (units.js) — только показ -----------------------
