  проверить('скобка с Цельсием после °F уходит', т('dmy', 'f', '54°F (12°C)') === '54°F' && т('dmy', 'f', 'ночь, 19°C (66°F), гроза') === 'ночь, 66°F, гроза');
  Е.задатьЕдиницы({ dateFormat: 'ymd', tempUnit: 'f' });
  проверить('разметка: атрибуты и <style> не трогаем', Е.htmlВФормате('<i title="17.10.2024">17.10.2024 0°C</i><style>.a{}</style>') === '<i title="17.10.2024">2024/10/17 32°F</i><style>.a{}</style>');
  проверить('градусы: °F без знака, дробь', Е.градусы(-5) === '23°' && Е.градусы(37.2, { дробь: true }) === '99.0°');
  проверить('введённая дата ложится как день.месяц.год', Е.датаВХранение('суббота, 2026/11/14', 'ymd') === 'суббота, 14.11.2026'
    && Е.датаВХранение('Sat, 11/14/2026', 'mdy') === 'Sat, 14.11.2026' && Е.датаВХранение('2026年11月14日', 'cjk') === '14.11.2026');
  // Время и ветер.
  const в = (о, s) => { Е.задатьЕдиницы(о); return Е.текстВФормате(s); };
  проверить('12 часов: время суток', в({ timeFormat: '12' }, '17:20; 01:40 | ночь; 00:05; 12:30; 10:00–12:00') === '5:20 PM; 1:40 AM | ночь; 12:05 AM; 12:30 PM; 10:00 AM–12:00 PM');
  проверить('12 часов: длительности и уже двенадцатичасовое не трогаем', в({ timeFormat: '12' }, 'голосовое 0:42; \u206005:12; 1:23:45; 9:05 вечера; 9:40 PM') === 'голосовое 0:42; \u206005:12; 1:23:45; 9:05 вечера; 9:40 PM');
  Е.задатьЕдиницы({ timeFormat: '12' });
