  проверить('ветер: м/с → км/ч, диапазон, письмо единицы', в({ windUnit: 'kmh' }, 'ветер 5 м/с, порывы 10-15 м/с; wind 20 mph; 3 мм') === 'ветер 18 км/ч, порывы 36-54 км/ч; wind 32 km/h; 3 мм');
  проверить('ветер: км/ч → м/с, mph; китайский вплотную', в({ windUnit: 'ms' }, '18 км/ч; 30 km/h') === '5 км/ч'.replace('5 км/ч', '5 м/с') + '; 8.3 m/s' && в({ windUnit: 'kmh' }, '风速5米/秒') === '风速18公里/小时');
