    проверить('игрок: опыт есть или прошедшее — без плашки', !/hud-virgin-pill/.test(карта({ 'Внешность': 'Ж, 19 лет, девственница', 'Количество партнеров': '2' })) && !/hud-virgin-pill/.test(карта({ 'Внешность': 'Ж, была девственницей' })));
