// Доверие и отношения: игрок всегда первым, хоть с минусом.
группа('игрок первым в доверии и отношениях');
{
  const Ch = await модуль('render/character.js'), VS = await модуль('render/views-story.js');
  const И = (v) => Ch.игрокПервым(v, 'Мари');
  проверить('общая фамилия Ким не поднимает чужую строку доверия', Ch.игрокПервым('Ким Намджун: 80; Ким Тэхен: 20', 'Ким Тэхен') === 'Ким Тэхен: 20; Ким Намджун: 80');
  N.запомнитьРазныхЛюдей(['Ким Намджун', 'Ким Тэхен']);
  проверить('Ким без личного имени не выбирает чужую карточку', !N.namesLikelySame('Ким', 'Ким Намджун') && N.namesLikelySame('Ким Намджун', 'Kim Namjun'));
  проверить('доверие: игрок с минусом — первым, остальные в прежнем порядке', И('Дамиан: 80; Лена: 40; Мари Лис: -60') === 'Мари Лис: -60; Дамиан: 80; Лена: 40', И('Дамиан: 80; Лена: 40; Мари Лис: -60'));
  проверить('уже первым или нет в списке — строка как есть', И('Мари: 10; Дамиан: 5') === 'Мари: 10; Дамиан: 5' && И('Дамиан: 5; Лена: 1') === 'Дамиан: 5; Лена: 1');
  проверить('отношения через перевод строки, игрок в группе', И('Лена: подруга\nОстин, Мари: соседи') === 'Остин, Мари: соседи; Лена: подруга');
  проверить('одна запись и запятые внутри пункта — без перестановки', И('Дамиан: друг, опекун, заменил отца') === 'Дамиан: друг, опекун, заменил отца');
  проверить('«Мари (жена)» — тоже игрок', И('Дамиан: брат; Мари (жена): любовь') === 'Мари (жена): любовь; Дамиан: брат');
  const { settings } = await модуль('settings.js'), заметки = await модуль('turn-notes.js');
  const прежде = { trustView: settings.trustView, trustScarsView: settings.trustScarsView, enableScars: settings.enableScars };
  const имена = ['Лена', 'Нина', 'Борис', 'Мари'];
  const сдвиги = Object.fromEntries(имена.map(имя => [имя, { d: -2 }]));
  const сведения = Object.fromEntries(имена.map(к => [к, { кто: 'Дамиан', к, v: 10, ступень: { min: 0, name: 'Знакомые' } }]));
  const порядок = ['Мари', 'Лена', 'Нина', 'Борис'];
  заметки.задатьПримерЗаметок({ сдвиги: имена.map(кому => ({ кто: 'Дамиан', кому, шрам: true, было: 95, стало: 75, почему: 'Старая ссора', id: кому })) });
  try {
    Object.assign(settings, { enableScars: true, trustScarsView: 'classic' });
    for (const вид of ['bars', 'hearts', 'shield', 'ring', 'traffic', 'spectrum', 'orbit']) {
      settings.trustView = вид;
      const html = Ch.содержимоеДоверия('Дамиан', 'Лена: 40; Нина: 18; Борис, Мари: -10', сведения, сдвиги);
      равно(вид + ': порядок ступеней при обновлении доверия', [...html.matchAll(/data-hud-trust="lock" [^>]*?data-to="([^"]+)"/g)].map(m => m[1]), порядок);
    }
    settings.trustView = 'bars';
    const html = Ch.содержимоеДоверия('Дамиан', имена.map(имя => имя + ': 30 (помогла)').join('; '), сведения, сдвиги);
    for (const вид of ['changes', 'reasons', 'scars']) {
      const блок = html.split('data-hud-list="' + вид + '">')[1]?.split('</div>')[0] || '';
      равно(вид + ': игрок виден до раскрытия списка', [...блок.matchAll(/<b>([^<]+)<\/b>/g)].map(m => m[1]), порядок);
    }
    for (const метка of ['user', '{{user}}']) {
      const карточка = Ch.buildCharacterHTML({ Имя: 'Дамиан', Доверие: 'Лена: 40; ' + метка + ': -10' }, 'test-player-first', true, false);
      равно('первое открытие карточки с меткой ' + метка, [...карточка.matchAll(/class="hud-zone-name">([^<]+)</g)].map(m => m[1]), [метка, 'Лена']);
    }
  } finally {
    Object.assign(settings, прежде);
    заметки.задатьПримерЗаметок(null);
  }
  const книжка = VS.видОтношений('Аня: подруга; Борис: враг; Мари: жена', 'book');
  проверить('записная книжка: игрок первым, дальше по алфавиту', книжка.indexOf('>Мари<') < книжка.indexOf('>Аня<') && книжка.indexOf('>Аня<') < книжка.indexOf('>Борис<'), книжка.slice(0, 300));
}

// «Как в Таверне» (tavern-theme.js): тема HUD из темы SillyTavern.
